files.content:
.sku {
  display: inline-block;
  font-family: var(--font-mono);
  font-size: var(--type-xs);
  letter-spacing: var(--tracking-sku);
  text-transform: uppercase;
  color: var(--fg-1);
  padding: 2px 6px;
  border: var(--rule-thin);
  background: var(--bg-1);
  white-space: nowrap;
}

.sku--accent { color: var(--accent-fg); background: var(--accent); border-color: var(--accent); }

.sku--ghost  { background: transparent; }

.btn {
  --btn-pad-x: var(--space-5);
  --btn-pad-y: var(--space-3);
  appearance: none;
  display: inline-flex;
  align-items: center;
  gap: var(--space-3);
  font-family: var(--font-body);
  font-size: var(--type-sm);
  font-weight: 500;
  line-height: 1;
  letter-spacing: var(--tracking-normal);
  padding: var(--btn-pad-y) var(--btn-pad-x);
  border: var(--rule-strong);
  background: var(--bg-1);
  color: var(--fg-0);
  cursor: pointer;
  border-radius: var(--radius-sm);
  text-decoration: none;
  transition: background var(--dur-flip) var(--ease-out),
              color var(--dur-flip) var(--ease-out),
              border-color var(--dur-flip) var(--ease-out);
}

.btn:hover  { background: var(--fg-0); color: var(--bg-0); border-color: var(--fg-0); }

.btn:active { background: var(--accent-active); color: var(--accent-fg); border-color: var(--accent-active); }

.btn:focus-visible { outline: 0; box-shadow: var(--shadow-focus); }

.btn--primary   { background: var(--accent); border-color: var(--accent); color: var(--accent-fg); }

.btn--primary:hover { background: var(--accent-hover); border-color: var(--accent-hover); }

.btn--primary:active { background: var(--accent-active); border-color: var(--accent-active); }

.btn--ghost  { background: transparent; border-color: var(--border-default); color: var(--fg-1); }

.btn--ghost:hover { background: var(--bg-2); color: var(--fg-0); border-color: var(--border-strong); }

.btn--quiet  { background: transparent; border-color: transparent; color: var(--fg-1); padding-inline: var(--space-3); }

.btn--quiet:hover { background: var(--bg-2); color: var(--fg-0); }

.btn--sm { font-size: var(--type-xs); padding: 4px var(--space-4); }

.btn--lg { font-size: var(--type-md); padding: var(--space-4) var(--space-6); }

.btn--icon { padding: var(--space-3); aspect-ratio: 1 / 1; }

.btn[disabled], .btn[aria-disabled="true"] {
  opacity: 0.5; cursor: not-allowed; pointer-events: none;
}

.btn .kbd {
  font-family: var(--font-mono);
  font-size: 10px;
  letter-spacing: var(--tracking-wide);
  color: var(--fg-2);
  border: 1px solid var(--border-default);
  background: var(--bg-0);
  padding: 1px 4px;
}

.btn:hover .kbd { color: var(--bg-0); background: var(--fg-1); border-color: var(--fg-0); }

.btn--primary .kbd, .btn--primary:hover .kbd { color: var(--accent-fg); background: transparent; border-color: var(--accent-fg); }

.input,
.select,
.textarea {
  appearance: none;
  display: block;
  width: 100%;
  font: inherit;
  font-family: var(--font-body);
  font-size: var(--type-sm);
  color: var(--fg-0);
  background: var(--bg-3);
  border: var(--rule-thin);
  border-color: var(--border-default);
  padding: var(--space-3) var(--space-4);
  border-radius: var(--radius-sm);
  transition: border-color var(--dur-flip) var(--ease-out);
}

.input::placeholder, .textarea::placeholder { color: var(--fg-3); }

.input:hover, .select:hover, .textarea:hover { border-color: var(--border-strong); }

.input:focus, .select:focus, .textarea:focus {
  outline: 0;
  border-color: var(--accent);
  background: var(--bg-1);
  box-shadow: 0 0 0 2px var(--accent-tint);
}

.input[aria-invalid="true"] {
  border-color: var(--status-error);
  box-shadow: 0 0 0 2px color-mix(in oklab, var(--status-error) 24%, transparent);
}

.input--mono { font-family: var(--font-mono); }

.switch {
  --sw-w: 36px;
  --sw-h: 18px;
  position: relative;
  width: var(--sw-w);
  height: var(--sw-h);
  background: var(--bg-3);
  border: var(--rule-thin);
  border-color: var(--border-default);
  cursor: pointer;
  display: inline-block;
  transition: background var(--dur-flip) var(--ease-out);
}

.switch::after {
  content: "";
  position: absolute;
  inset: 1px auto 1px 1px;
  width: calc(var(--sw-h) - 4px);
  background: var(--fg-1);
  transition: transform var(--dur-flip) var(--ease-out), background var(--dur-flip) var(--ease-out);
}

.switch[aria-checked="true"] { background: var(--accent); border-color: var(--accent); }

.switch[aria-checked="true"]::after {
  transform: translateX(calc(var(--sw-w) - var(--sw-h)));
  background: var(--accent-fg);
}

.switch:focus-visible { outline: 0; box-shadow: var(--shadow-focus); }

.badge {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-family: var(--font-mono);
  font-size: 10px;
  letter-spacing: var(--tracking-sku);
  text-transform: uppercase;
  font-weight: 600;
  padding: 2px 6px;
  border: 1px solid currentColor;
  background: transparent;
}

.badge--accent  { color: var(--accent); }

.badge--success { color: var(--status-success); }

.badge--warn    { color: var(--status-warn); }

.badge--error   { color: var(--status-error); }

.badge--info    { color: var(--status-info); }

.badge--solid {
  border-color: currentColor;
  background: currentColor;
}

.badge--solid.badge--accent  { color: var(--accent-fg); background: var(--accent); border-color: var(--accent); }

kbd, .kbd {
  font-family: var(--font-mono);
  font-size: 11px;
  letter-spacing: var(--tracking-wide);
  background: var(--bg-2);
  color: var(--fg-1);
  border: 1px solid var(--border-default);
  padding: 1px 6px;
  display: inline-block;
  vertical-align: baseline;
  border-radius: 0;
}

:root {
  --bg-0: oklch(97.5% 0.008 78);
  --bg-1: oklch(95.5% 0.010 78);
  --bg-2: oklch(93.0% 0.012 78);
  --bg-3: oklch(89.5% 0.014 78);
  --border-default: oklch(74% 0.016 65);
  --border-strong: oklch(48% 0.022 60);
  --fg-0: oklch(20% 0.020 50);
  --fg-1: oklch(38% 0.018 50);
  --fg-2: oklch(52% 0.015 50);
  --fg-3: oklch(68% 0.012 50);
  --accent: oklch(56% 0.170 50);
  --accent-hover: oklch(50% 0.170 50);
  --accent-active: oklch(44% 0.170 50);
  --accent-fg: oklch(98% 0.008 78);
  --accent-tint: oklch(92% 0.040 55);
  --status-success: oklch(48% 0.14 145);
  --status-warn: oklch(64% 0.16  88);
  --status-error: oklch(50% 0.20  25);
  --status-info: oklch(50% 0.13 230);
  --radius-sm: 2px;
  --space-3: 8px;
  --space-4: 12px;
  --space-5: 16px;
  --space-6: 24px;
  --font-body: 'Berkeley Mono', 'TX-02', 'JetBrains Mono', 'IBM Plex Mono', ui-monospace, SFMono-Regular, Menlo, monospace;
  --font-mono: 'Berkeley Mono', 'TX-02', 'JetBrains Mono', 'IBM Plex Mono', ui-monospace, SFMono-Regular, Menlo, monospace;
  --type-xs: 11px;
  --type-sm: 12px;
  --type-md: 15px;
  --tracking-normal: 0;
  --tracking-wide: 0.04em;
  --tracking-sku: 0.12em;
  --dur-flip: 90ms;
  --ease-out: cubic-bezier(0.22, 1, 0.36, 1);
  --rule-thin: 1px solid var(--border-default);
  --rule-strong: 1px solid var(--border-strong);
  --shadow-focus: 0 0 0 2px var(--accent);
  --bg-0: oklch(13% 0.012 60);
  --bg-1: oklch(17% 0.014 60);
  --bg-2: oklch(20% 0.016 60);
  --bg-3: oklch(24% 0.018 60);
  --border-default: oklch(40% 0.022 60);
  --border-strong: oklch(58% 0.026 60);
  --fg-0: oklch(94% 0.014 80);
  --fg-1: oklch(78% 0.014 80);
  --fg-2: oklch(60% 0.012 80);
  --fg-3: oklch(44% 0.010 80);
  --accent: oklch(72% 0.160 55);
  --accent-hover: oklch(78% 0.160 55);
  --accent-active: oklch(84% 0.160 55);
  --accent-fg: oklch(14% 0.020 50);
  --accent-tint: oklch(28% 0.060 55);
  --status-success: oklch(72% 0.16 145);
  --status-warn: oklch(80% 0.16  88);
  --status-error: oklch(68% 0.20  25);
  --status-info: oklch(72% 0.13 230);
  --shadow-focus: 0 0 0 2px var(--accent);
  --bg-0: oklch(13% 0.012 60);
  --bg-1: oklch(17% 0.014 60);
  --bg-2: oklch(20% 0.016 60);
  --bg-3: oklch(24% 0.018 60);
  --border-default: oklch(40% 0.022 60);
  --border-strong: oklch(58% 0.026 60);
  --fg-0: oklch(94% 0.014 80);
  --fg-1: oklch(78% 0.014 80);
  --fg-2: oklch(60% 0.012 80);
  --fg-3: oklch(44% 0.010 80);
  --accent: oklch(72% 0.160 55);
  --accent-hover: oklch(78% 0.160 55);
  --accent-active: oklch(84% 0.160 55);
  --accent-fg: oklch(14% 0.020 50);
  --accent-tint: oklch(28% 0.060 55);
  --dur-flip: 1ms;
}
